import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;import java.util.ArrayList;class TestClass {static class DSU {int[] parent;public DSU(int n) {parent = new int[n];for (int i = 0; i < n; i++) parent[i] = i;}public int find(int i) {if (parent[i] == i) return i;return parent[i] = find(parent[i]);}public boolean union(int i, int j) {int rootI = find(i);int rootJ = find(j);if (rootI != rootJ) {parent[rootI] = rootJ;return true;}return false;}}public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));int n = Integer.parseInt(br.readLine().trim());int[] a = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());int maxVal = 0;for (int i = 0; i < n; i++) {a[i] = Integer.parseInt(st.nextToken());if (a[i] > maxVal) maxVal = a[i];}ArrayList<Integer>[] multiples = new ArrayList[maxVal + 1];for (int i = 0; i < n; i++) {int val = a[i];for (int j = 1; j * j <= val; j++) {if (val % j == 0) {if (multiples[j] == null) multiples[j] = new ArrayList<Integer>();multiples[j].add(i);if (j * j != val) {int other = val / j;if (multiples[other] == null) multiples[other] = new ArrayList<Integer>();multiples[other].add(i);}}}}DSU dsu = new DSU(n);long totalCost = 0;int edgesCount = 0;for (int d = maxVal; d >= 1; d--) {if (multiples[d] != null && multiples[d].size() > 1) {for (int i = 0; i < multiples[d].size() - 1; i++) {int u = multiples[d].get(i);int v = multiples[d].get(i + 1);if (dsu.union(u, v)) {totalCost += d;edgesCount++;if (edgesCount == n - 1) break;}}}if (edgesCount == n - 1) break;}System.out.println(totalCost);}}